// 本文件定义 Bubble Tea TUI 对外暴露的 UI 适配器。
package bubble

import (
	"context"
	"errors"
	"fmt"
	tea "github.com/charmbracelet/bubbletea"
	"gocode/internal/message"
	"gocode/internal/model"
	"gocode/internal/session"
	"gocode/internal/settings"
	"gocode/internal/subagent"
	"gocode/internal/ui"
	"os"
	"sync"
)

// Runner 描述 TUI 提交一轮用户输入时需要调用的对话运行器。
type Runner interface {
	RunTurn(ctx context.Context, input string) (message.Message, error)
	ResetHistory()
	LoadHistory(ctx context.Context, sessionID string) error
}

// SupplementSubmitter describes runners that can accept instructions while a
// model turn is already running.
type SupplementSubmitter interface {
	SubmitSupplement(input string) bool
}

// SupplementStatsProvider exposes pending supplement counts for status UI.
type SupplementStatsProvider interface {
	PendingSupplementCount() int
}

// SessionStore 描述 TUI 列举和管理会话所需的最小接口。
type SessionStore interface {
	ListSessions(ctx context.Context) ([]session.SessionSummary, error)
}

// ModelConfigController 描述运行时读取和应用模型配置的控制器。
type ModelConfigController interface {
	CurrentModelConfig() model.Config
	ApplyModelConfig(model.Config) error
}

// ModelConfigSaver 描述可将模型配置持久化到磁盘的控制器扩展。
type ModelConfigSaver interface {
	SaveModelConfig(model.Config) error
}

// SettingsController 描述运行时读取和保存 UI/agent 设置的控制器。
type SettingsController interface {
	CurrentSettings() settings.Config
	SaveSettings(settings.Config) error
}

// SubagentController 描述 TUI 手动启动和查看 subagent 所需的能力。
type SubagentController interface {
	Run(context.Context, subagent.Request) (subagent.Result, error)
	Launch(context.Context, subagent.Request) (subagent.TaskSnapshot, error)
	ListTasks() []subagent.TaskSnapshot
}

// UI 是基于 Bubble Tea 的交互式终端界面实现。
type UI struct {
	mu                    sync.Mutex
	program               *tea.Program
	modelConfigController ModelConfigController
	settingsController    SettingsController
	subagentController    SubagentController
	sessionStore          SessionStore
}

// 确保 UI 满足通用终端 UI 接口。
var _ ui.UI = (*UI)(nil)

// New 创建一个尚未启动的 Bubble Tea UI 实例。
func New() *UI {
	return &UI{}
}

// SetModelConfigController 注入模型配置控制器，供 /model 向导读取和保存配置。
func (u *UI) SetModelConfigController(controller ModelConfigController) {
	u.mu.Lock()
	defer u.mu.Unlock()
	u.modelConfigController = controller
}

// SetSettingsController 注入 settings 控制器，供 /setting 和状态栏读取。
func (u *UI) SetSettingsController(controller SettingsController) {
	u.mu.Lock()
	defer u.mu.Unlock()
	u.settingsController = controller
}

// SetSubagentController 注入 subagent 控制器，供 /subagent 和 /tasks 使用。
func (u *UI) SetSubagentController(controller SubagentController) {
	u.mu.Lock()
	defer u.mu.Unlock()
	u.subagentController = controller
}

// SetSessionStore 注入 session store，供 /sessions 命令列举历史会话。
func (u *UI) SetSessionStore(store SessionStore) {
	u.mu.Lock()
	defer u.mu.Unlock()
	u.sessionStore = store
}

// Run 启动 Bubble Tea 主循环，并把输出写入带光标锚点修正的终端流。
func (u *UI) Run(ctx context.Context, runner Runner, sessionID string) error {
	u.mu.Lock()
	controller := u.modelConfigController
	settingsController := u.settingsController
	subagentController := u.subagentController
	sessionStore := u.sessionStore
	u.mu.Unlock()

	anchor := newTerminalCursorAnchor()
	appModel := newModel(ctx, runner, sessionID, controller, settingsController, subagentController, sessionStore, anchor)
	program := tea.NewProgram(
		appModel,
		tea.WithContext(ctx),
		tea.WithOutput(newAnchoredOutput(os.Stdout, anchor)),
		tea.WithAltScreen(),
		tea.WithMouseCellMotion(),
	)

	u.mu.Lock()
	u.program = program
	u.mu.Unlock()

	_, err := program.Run()

	u.mu.Lock()
	if u.program == program {
		u.program = nil
	}
	u.mu.Unlock()

	if errors.Is(err, tea.ErrInterrupted) {
		return nil
	}
	return err
}

// OnAssistantDelta 接收模型流式文本增量，并转发给 Bubble Tea 状态机。
func (u *UI) OnAssistantDelta(text string) error {
	if text == "" {
		return nil
	}
	return u.send(assistantDeltaMsg(text))
}

// OnThinkingDelta 接收模型 thinking 流，并转发给 Bubble Tea 状态机。
func (u *UI) OnThinkingDelta(text string) error {
	if text == "" {
		return nil
	}
	return u.send(thinkingDeltaMsg(text))
}

// OnToolCall 接收工具调用事件，并转发给 Bubble Tea 状态机展示。
func (u *UI) OnToolCall(event ui.ToolCallEvent) error {
	return u.send(toolCallMsg(event))
}

// OnToolResult 接收工具结果事件，并转发给 Bubble Tea 状态机展示。
func (u *UI) OnToolResult(event ui.ToolResultEvent) error {
	return u.send(toolResultMsg(event))
}

// OnDone 通知 TUI 当前 assistant 响应已经结束。
func (u *UI) OnDone() error {
	return u.send(doneMsg{})
}

// ConsumesOldContent 声明 bubble UI 会消费 OldContent 用于 diff 展示。
func (u *UI) ConsumesOldContent() bool { return true }

// OnSystemMessage 接收后台任务等系统事件，并转发给 Bubble Tea 状态机展示。
func (u *UI) OnSystemMessage(event ui.SystemEvent) error {
	return u.send(systemEventMsg(event))
}

// send 将外部事件安全地投递到正在运行的 Bubble Tea program。
func (u *UI) send(msg tea.Msg) error {
	u.mu.Lock()
	program := u.program
	u.mu.Unlock()
	if program == nil {
		return fmt.Errorf("bubble UI program is not running")
	}
	program.Send(msg)
	return nil
}

// 本文件定义输入框提交、斜杠命令、终端模式和历史输入导航行为。
package bubble

import (
	"github.com/charmbracelet/bubbles/textarea"
	tea "github.com/charmbracelet/bubbletea"
	"strings"
	"time"
)

// handleSubmit 处理 Enter 提交，根据输入内容分派到聊天、命令或终端执行路径。
func (m appModel) handleSubmit() (tea.Model, tea.Cmd) {
	m.reconcileLegacyRunningState()
	var line string
	var ok bool
	m, line, ok = m.consumeSubmittedInput()
	if !ok {
		return m, nil
	}

	if isExitCommandInput(line) {
		m.rememberInputHistory(line)
		_, cmd := m.handleCommand(line)
		return m, cmd
	}
	if line == "!" {
		m.toggleTerminalMode()
		return m, nil
	}
	if m.terminalMode {
		m.rememberInputHistory(line)
		return m.submitShellCommand(line)
	}
	if command, ok := shellCommandFromBang(line); ok {
		if m.isWorkRunning() {
			m.addEntry(transcriptEntry{kind: entrySystem, title: "busy", body: "terminal commands are unavailable while a turn is running"})
			return m, nil
		}
		m.rememberInputHistory(line)
		return m.submitShellCommand(command)
	}

	if handled, cmd := m.handleCommand(line); handled {
		return m, cmd
	}

	if m.isModelWorkRunning() {
		return m.submitSupplement(line), nil
	}
	if m.isTerminalWorkRunning() {
		m.addEntry(transcriptEntry{kind: entrySystem, title: "busy", body: "chat is unavailable while a terminal command is running"})
		return m, nil
	}

	m.rememberInputHistory(line)
	return m.startChatTurn(line)
}

func (m appModel) handleQueueSubmit() (tea.Model, tea.Cmd) {
	var line string
	var ok bool
	m, line, ok = m.consumeSubmittedInput()
	if !ok {
		return m, nil
	}
	if m.isModelWorkRunning() {
		return m.queueChatInput(line), nil
	}
	m.input.SetValue(line)
	m.input.CursorEnd()
	m.syncInputMode()
	m.relayout()
	return m, nil
}

func (m appModel) consumeSubmittedInput() (appModel, string, bool) {
	line := strings.TrimSpace(m.input.Value())
	if line == "" {
		return m, "", false
	}
	m.input.Reset()
	m.resetHistoryNavigation()
	m.syncInputMode()
	m.relayout()

	if continued, text := splitContinuation(line); continued {
		m.rememberInputHistory(line)
		m.pending = append(m.pending, text)
		m.refreshViewport()
		return m, "", false
	}

	if len(m.pending) > 0 {
		m.pending = append(m.pending, line)
		line = strings.Join(m.pending, "\n")
		m.pending = nil
	}
	return m, line, true
}

// handleCommand 处理内置 TUI 命令。除 exit/quit 外，命令仍要求以斜杠开头。
func (m *appModel) handleCommand(line string) (bool, tea.Cmd) {
	trimmed := strings.TrimSpace(line)
	if !strings.HasPrefix(trimmed, "/") && !isBareExitCommand(trimmed) {
		return false, nil
	}
	if m.commandRegistry == nil {
		m.commandRegistry = NewCommandRegistry()
	}
	return m.commandRegistry.Dispatch(m, line)
}

func isExitCommandInput(line string) bool {
	trimmed := strings.TrimSpace(line)
	return trimmed == "/exit" || trimmed == "/quit" || isBareExitCommand(trimmed)
}

func isBareExitCommand(line string) bool {
	return line == "exit" || line == "quit"
}

// toggleTerminalMode 切换持续终端模式，并在 transcript 中写入状态提示。
func (m *appModel) toggleTerminalMode() {
	m.terminalMode = !m.terminalMode
	m.pending = nil
	m.activeAssistant = -1
	m.applyCursorAnimation()
	state := "terminal mode disabled"
	if m.terminalMode {
		state = "terminal mode enabled"
	}
	m.addEntry(transcriptEntry{
		kind:  entrySystem,
		title: "terminal",
		body:  state,
	})
}

// isTerminalInputActive 判断当前输入框是否需要展示终端模式视觉状态。
func (m appModel) isTerminalInputActive() bool {
	return m.terminalMode || m.terminalPreview
}

// hasMultilineInput 判断当前输入是否处于多行输入或续行状态。
func (m appModel) hasMultilineInput() bool {
	return len(m.pending) > 0 || strings.Contains(m.input.Value(), "\n")
}

// syncInputMode 根据当前文本同步一次性终端预览状态。
func (m *appModel) syncInputMode() {
	m.terminalPreview = hasBangPrefix(m.input.Value())
}

// handleInputVerticalNavigation 让上下键先在多行文本内移动，抵达边界后再切换历史输入。
func (m appModel) handleInputVerticalNavigation(direction int) (tea.Model, tea.Cmd) {
	if m.isTerminalWorkRunning() {
		return m, nil
	}

	if direction < 0 {
		if canMoveTextareaUp(m.input) {
			return m.updateInputWithKey(tea.KeyMsg{Type: tea.KeyUp})
		}
		if !textareaCursorAtStart(m.input) {
			m.input.CursorStart()
			m.syncInputMode()
			m.applyCursorAnimation()
			return m, nil
		}
		return m.handleHistoryNavigation(-1)
	}

	if canMoveTextareaDown(m.input) {
		return m.updateInputWithKey(tea.KeyMsg{Type: tea.KeyDown})
	}
	if !textareaCursorAtEnd(m.input) {
		m.input.CursorEnd()
		m.historyDownLock = false
		m.syncInputMode()
		m.applyCursorAnimation()
		return m, nil
	}
	if m.historyDownLock && m.historyIndex != -1 {
		m.historyDownLock = false
		return m, nil
	}
	return m.handleHistoryNavigation(1)
}

func (m appModel) submitSupplement(line string) appModel {
	line = strings.TrimSpace(line)
	if line == "" {
		return m
	}
	m.rememberInputHistory(line)
	submitter, ok := m.runner.(SupplementSubmitter)
	if !ok || !submitter.SubmitSupplement(line) {
		m.addEntry(transcriptEntry{
			kind:  entrySystem,
			title: "supplement",
			body:  "runner does not support running-turn supplements",
		})
		return m
	}
	m.addEntry(transcriptEntry{
		kind:  entryUser,
		title: "you (supplement)",
		body:  line,
	})
	return m
}

// startChatTurn records and starts a model turn when the guard is idle.
func (m appModel) startChatTurn(line string) (appModel, tea.Cmd) {
	line = strings.TrimSpace(line)
	if line == "" {
		return m, nil
	}
	if !m.queryGuard.StartModel() {
		m.addEntry(transcriptEntry{kind: entrySystem, title: "busy", body: "assistant is already running"})
		return m, nil
	}
	m.addEntry(transcriptEntry{
		kind:  entryUser,
		title: "you",
		body:  line,
	})
	m.turnStartedAt = time.Now()
	m.syncRunningFlags()
	m.activeAssistant = -1
	return m, runTurnCmd(m.ctx, m.runner, line)
}

// queueChatInput records a chat input for FIFO execution after the active turn.
func (m appModel) queueChatInput(line string) appModel {
	line = strings.TrimSpace(line)
	if line == "" {
		return m
	}
	m.rememberInputHistory(line)
	if m.chatQueue.Enqueue(line) {
		m.addEntry(transcriptEntry{
			kind:  entryUser,
			title: "you (queued)",
			body:  line,
		})
		m.addEntry(transcriptEntry{
			kind:  entrySystem,
			title: "queued",
			body:  "queued for next turn",
		})
	}
	return m
}

// updateInputWithKey 将按键交给 textarea 处理，并同步输入模式、布局和光标动画。
func (m appModel) updateInputWithKey(msg tea.KeyMsg) (tea.Model, tea.Cmd) {
	input, cmd := m.input.Update(msg)
	m.input = input
	m.syncInputMode()
	m.relayout()
	m.applyCursorAnimation()
	return m, cmd
}

// canMoveTextareaUp 判断 textarea 光标是否还能向上移动到上一行或上方可视行。
func canMoveTextareaUp(input textarea.Model) bool {
	lineInfo := input.LineInfo()
	return input.Line() > 0 || lineInfo.RowOffset > 0
}

// canMoveTextareaDown 判断 textarea 光标是否还能向下移动到下一行或下方可视行。
func canMoveTextareaDown(input textarea.Model) bool {
	lineInfo := input.LineInfo()
	return input.Line() < input.LineCount()-1 || lineInfo.RowOffset < lineInfo.Height-1
}

// textareaCursorAtStart 判断 textarea 光标是否位于当前输入的逻辑开头。
func textareaCursorAtStart(input textarea.Model) bool {
	if canMoveTextareaUp(input) {
		return false
	}
	lineInfo := input.LineInfo()
	cursorLine := input.Line()
	copyInput := input
	copyInput.CursorStart()
	startInfo := copyInput.LineInfo()
	return cursorLine == copyInput.Line() &&
		lineInfo.RowOffset == startInfo.RowOffset &&
		lineInfo.ColumnOffset == startInfo.ColumnOffset
}

// textareaCursorAtEnd 判断 textarea 光标是否位于当前输入的逻辑末尾。
func textareaCursorAtEnd(input textarea.Model) bool {
	if canMoveTextareaDown(input) {
		return false
	}
	lineInfo := input.LineInfo()
	cursorLine := input.Line()
	copyInput := input
	copyInput.CursorEnd()
	endInfo := copyInput.LineInfo()
	return cursorLine == copyInput.Line() &&
		lineInfo.RowOffset == endInfo.RowOffset &&
		lineInfo.ColumnOffset == endInfo.ColumnOffset
}

// handleHistoryNavigation 在输入边界处切换历史记录，并保留进入历史前的草稿。
func (m appModel) handleHistoryNavigation(direction int) (tea.Model, tea.Cmd) {
	if m.running || len(m.inputHistory) == 0 {
		return m, nil
	}

	if direction < 0 {
		m.historyDownLock = false
		if m.historyIndex == -1 {
			m.historyDraft = m.input.Value()
			m.historyIndex = len(m.inputHistory) - 1
		} else if m.historyIndex > 0 {
			m.historyIndex--
		}
		m.input.SetValue(m.inputHistory[m.historyIndex])
		m.input.CursorEnd()
		m.syncInputMode()
		m.relayout()
		m.applyCursorAnimation()
		return m, nil
	}

	if m.historyIndex == -1 {
		return m, nil
	}
	if m.historyIndex < len(m.inputHistory)-1 {
		m.historyIndex++
		m.input.SetValue(m.inputHistory[m.historyIndex])
		m.historyDownLock = true
	} else {
		m.historyIndex = -1
		m.input.SetValue(m.historyDraft)
		m.historyDraft = ""
		m.historyDownLock = false
	}
	m.input.CursorEnd()
	m.syncInputMode()
	m.relayout()
	m.applyCursorAnimation()
	return m, nil
}

// rememberInputHistory 记录一条非空且不重复的用户输入历史。
func (m *appModel) rememberInputHistory(line string) {
	line = strings.TrimSpace(line)
	if line == "" {
		return
	}
	if len(m.inputHistory) > 0 && m.inputHistory[len(m.inputHistory)-1] == line {
		return
	}
	m.inputHistory = append(m.inputHistory, line)
}

// resetHistoryNavigation 清除当前历史浏览状态，回到普通编辑模式。
func (m *appModel) resetHistoryNavigation() {
	m.historyIndex = -1
	m.historyDraft = ""
	m.historyDownLock = false
}

// submitShellCommand 提交终端命令，先写入 transcript，再异步执行 bash。
func (m appModel) submitShellCommand(command string) (tea.Model, tea.Cmd) {
	command = strings.TrimSpace(command)
	if command == "" {
		return m, nil
	}
	if !m.queryGuard.StartTerminal() {
		m.addEntry(transcriptEntry{kind: entrySystem, title: "busy", body: "terminal commands are unavailable while work is running"})
		return m, nil
	}
	m.addEntry(transcriptEntry{
		kind:  entryTool,
		title: "terminal",
		body:  "$ " + command,
	})
	m.syncRunningFlags()
	m.activeAssistant = -1
	return m, runShellCmd(m.ctx, command)
}

package bubble

import (
	"fmt"
	"sort"
	"strings"

	tea "github.com/charmbracelet/bubbletea"
)

// CommandHandler mutates appModel for a slash command and may return a tea.Cmd.
type CommandHandler func(m *appModel, invocation string) tea.Cmd

// Command describes one registered slash command.
type Command struct {
	Name              string
	Aliases           []string
	Description       string
	ArgumentHint      string
	AllowWhileRunning bool
	Handler           CommandHandler
}

// CommandRegistry resolves and dispatches registered slash commands.
type CommandRegistry struct {
	commands map[string]Command
	order    []string
}

// NewCommandRegistry creates the default TUI command registry.
func NewCommandRegistry() *CommandRegistry {
	registry := &CommandRegistry{}
	registry.Register(Command{
		Name:              "/help",
		Description:       "show available commands",
		AllowWhileRunning: true,
		Handler: func(m *appModel, invocation string) tea.Cmd {
			m.addEntry(transcriptEntry{kind: entrySystem, title: "help", body: m.commandRegistry.HelpText()})
			return nil
		},
	})
	registry.Register(Command{
		Name:              "/model",
		Description:       "open the model switcher",
		ArgumentHint:      "[status|custom|deepseek]",
		AllowWhileRunning: false,
		Handler: func(m *appModel, invocation string) tea.Cmd {
			return m.handleModelCommand(invocation)
		},
	})
	registry.Register(Command{
		Name:              "/export",
		Description:       "export the current conversation",
		ArgumentHint:      "[filename]",
		AllowWhileRunning: true,
		Handler: func(m *appModel, invocation string) tea.Cmd {
			m.handleExportCommand(invocation)
			return nil
		},
	})
	registry.Register(Command{
		Name:              "/setting",
		Description:       "open settings wizard",
		AllowWhileRunning: false,
		Handler: func(m *appModel, invocation string) tea.Cmd {
			m.settingWizard = newSettingWizard(m.currentSettings())
			m.pending = nil
			return nil
		},
	})
	registry.Register(Command{
		Name:              "/subagent",
		Description:       "launch a subagent",
		ArgumentHint:      "[--fork|--empty] [--background|--sync] <prompt>",
		AllowWhileRunning: false,
		Handler: func(m *appModel, invocation string) tea.Cmd {
			return m.handleSubagentCommand(invocation)
		},
	})
	registry.Register(Command{
		Name:              "/streamma",
		Description:       "run a prompt through StreamMA subagents",
		ArgumentHint:      "<prompt>",
		AllowWhileRunning: false,
		Handler: func(m *appModel, invocation string) tea.Cmd {
			return m.handleStreamMACommand(invocation)
		},
	})
	registry.Register(Command{
		Name:              "/streamma-trace",
		Description:       "run StreamMA with live event trace",
		ArgumentHint:      "<prompt>",
		AllowWhileRunning: false,
		Handler: func(m *appModel, invocation string) tea.Cmd {
			return m.handleStreamMACommand(invocation)
		},
	})
	registry.Register(Command{
		Name:              "/tasks",
		Description:       "show background subagent tasks",
		AllowWhileRunning: true,
		Handler: func(m *appModel, invocation string) tea.Cmd {
			m.handleTasksCommand()
			return nil
		},
	})
	registry.Register(Command{
		Name:              "/status",
		Description:       "show session status",
		AllowWhileRunning: true,
		Handler: func(m *appModel, invocation string) tea.Cmd {
			sessionID := m.sessionID
			if sessionID == "" {
				sessionID = "<none>"
			}
			m.addEntry(transcriptEntry{kind: entrySystem, title: "status", body: m.statusText(sessionID)})
			return nil
		},
	})
	registry.Register(Command{
		Name:              "/clear",
		Description:       "clear in-process chat history",
		AllowWhileRunning: false,
		Handler: func(m *appModel, invocation string) tea.Cmd {
			if m.runner != nil {
				m.runner.ResetHistory()
			}
			m.transcript = nil
			m.pending = nil
			m.chatQueue.Clear()
			m.activeAssistant = -1
			m.syncInputMode()
			m.addEntry(transcriptEntry{kind: entrySystem, title: "system", body: "history cleared"})
			return nil
		},
	})
	registry.Register(Command{
		Name:              "/sessions",
		Description:       "browse and restore previous sessions",
		AllowWhileRunning: false,
		Handler: func(m *appModel, invocation string) tea.Cmd {
			m.sessionPicker = newSessionPicker()
			m.pending = nil
			return loadSessionsCmd(m.ctx, m.sessionStore)
		},
	})
	registry.Register(Command{
		Name:              "/exit",
		Aliases:           []string{"/quit", "exit", "quit"},
		Description:       "quit the TUI",
		AllowWhileRunning: true,
		Handler: func(m *appModel, invocation string) tea.Cmd {
			m.queryGuard.Cancel()
			m.chatQueue.Clear()
			return tea.Quit
		},
	})
	return registry
}

// Register adds or replaces a slash command.
func (r *CommandRegistry) Register(command Command) {
	if r == nil || command.Name == "" || command.Handler == nil {
		return
	}
	if r.commands == nil {
		r.commands = make(map[string]Command)
	}
	name := strings.TrimSpace(command.Name)
	command.Name = name
	if _, exists := r.commands[name]; !exists {
		r.order = append(r.order, name)
	}
	r.commands[name] = command
	for _, alias := range command.Aliases {
		alias = strings.TrimSpace(alias)
		if alias != "" {
			r.commands[alias] = command
		}
	}
}

// Lookup resolves a command token to registered metadata.
func (r *CommandRegistry) Lookup(token string) (Command, bool) {
	if r == nil {
		return Command{}, false
	}
	command, ok := r.commands[strings.TrimSpace(token)]
	return command, ok
}

// Dispatch executes a registered slash command or writes stable feedback for
// malformed and unknown command inputs.
func (r *CommandRegistry) Dispatch(m *appModel, line string) (bool, tea.Cmd) {
	if m == nil || strings.TrimSpace(line) == "" {
		return false, nil
	}
	token := commandToken(line)
	if token == "" || token == "/" {
		m.addEntry(transcriptEntry{kind: entryError, title: "command", body: "invalid slash command"})
		return true, nil
	}

	command, ok := r.Lookup(token)
	if !ok {
		m.addEntry(transcriptEntry{kind: entryError, title: "command", body: fmt.Sprintf("unknown command: %s", token)})
		return true, nil
	}
	if m.isWorkRunning() && !command.AllowWhileRunning {
		m.addEntry(transcriptEntry{kind: entrySystem, title: "busy", body: fmt.Sprintf("%s is unavailable while a turn is running", token)})
		return true, nil
	}
	return true, command.Handler(m, line)
}

// HelpText renders command metadata in a deterministic order.
func (r *CommandRegistry) HelpText() string {
	if r == nil {
		return "No commands registered."
	}
	names := append([]string(nil), r.order...)
	sort.Strings(names)
	lines := []string{"Commands:"}
	for _, name := range names {
		command, ok := r.commands[name]
		if !ok {
			continue
		}
		label := command.Name
		if strings.TrimSpace(command.ArgumentHint) != "" {
			label += " " + strings.TrimSpace(command.ArgumentHint)
		}
		if len(command.Aliases) > 0 {
			aliases := append([]string(nil), command.Aliases...)
			sort.Strings(aliases)
			label += " (" + strings.Join(aliases, ", ") + ")"
		}
		lines = append(lines, fmt.Sprintf("%s - %s", label, command.Description))
	}
	lines = append(lines, "Type ! to toggle terminal mode or !<command> to run bash once.")
	return strings.Join(lines, "\n")
}

func commandToken(line string) string {
	line = strings.TrimSpace(line)
	if line == "" {
		return ""
	}
	fields := strings.Fields(line)
	if len(fields) == 0 {
		return line
	}
	return fields[0]
}

func (m *appModel) handleStreamMACommand(invocation string) tea.Cmd {
	invocation = strings.TrimSpace(invocation)
	task := strings.TrimSpace(strings.TrimPrefix(invocation, commandToken(invocation)))
	if task == "" {
		if commandToken(invocation) == "/streamma-trace" {
			m.addEntry(transcriptEntry{
				kind:  entrySystem,
				title: "streamma-trace",
				body:  "usage: /streamma-trace <prompt>\nRuns the same StreamMA DAG and prints live runtime events for step fanout inspection.",
			})
			return nil
		}
		m.addEntry(transcriptEntry{
			kind:  entrySystem,
			title: "streamma",
			body:  "usage: /streamma <prompt>\nRuns an adaptive StreamMA DAG with real subagent workers and END_STEP step exchange.",
		})
		return nil
	}
	m.rememberInputHistory(invocation)
	updated, cmd := m.startChatTurn(invocation)
	*m = updated
	return cmd
}

package bubble

import (
	"context"
	"fmt"
	tea "github.com/charmbracelet/bubbletea"
	"gocode/internal/model"
	"gocode/internal/settings"
	"gocode/internal/subagent"
	"os"
	"path/filepath"
	"strings"
	"time"
)

func commandArgs(invocation string) string {
	token := commandToken(invocation)
	return strings.TrimSpace(strings.TrimPrefix(strings.TrimSpace(invocation), token))
}

func (m *appModel) handleModelCommand(invocation string) tea.Cmd {
	args := strings.TrimSpace(commandArgs(invocation))
	switch args {
	case "":
		m.modelWizard = newModelWizard(m.currentModelConfig())
		m.pending = nil
	case "status":
		cfg := m.currentModelConfig()
		m.addEntry(transcriptEntry{
			kind:  entrySystem,
			title: "model",
			body:  fmt.Sprintf("provider=%s base=%s path=%s model=%s key=%s", cfg.Provider, cfg.APIBaseURL, cfg.APIPath, cfg.Model, cfg.APIKeyEnvName),
		})
	case model.ProviderCustom, model.ProviderDeepSeek:
		cfg, err := m.configForProvider(args)
		if err != nil {
			m.addEntry(transcriptEntry{kind: entryError, title: "model", body: err.Error()})
			return nil
		}
		m.applyModelConfigFromCommand(cfg)
	default:
		m.addEntry(transcriptEntry{kind: entryError, title: "model", body: fmt.Sprintf("unknown model command: %s", args)})
	}
	return nil
}

func (m *appModel) applyModelConfigFromCommand(cfg model.Config) {
	if m.modelConfig == nil {
		m.addEntry(transcriptEntry{kind: entryError, title: "model", body: "model config controller is unavailable"})
		return
	}
	if saver, ok := m.modelConfig.(ModelConfigSaver); ok {
		if err := saver.SaveModelConfig(cfg); err != nil {
			m.addEntry(transcriptEntry{kind: entryError, title: "model", body: err.Error()})
			return
		}
	}
	if err := m.modelConfig.ApplyModelConfig(cfg); err != nil {
		m.addEntry(transcriptEntry{kind: entryError, title: "model", body: err.Error()})
		return
	}
	m.addEntry(transcriptEntry{
		kind:  entrySystem,
		title: "model",
		body:  fmt.Sprintf("provider=%s base=%s path=%s model=%s key=%s", cfg.Provider, cfg.APIBaseURL, cfg.APIPath, cfg.Model, cfg.APIKeyEnvName),
	})
}

func (m *appModel) handleExportCommand(invocation string) {
	path, err := m.exportPath(commandArgs(invocation))
	if err != nil {
		m.addEntry(transcriptEntry{kind: entryError, title: "export", body: err.Error()})
		return
	}
	if err := os.MkdirAll(filepath.Dir(path), 0o755); err != nil {
		m.addEntry(transcriptEntry{kind: entryError, title: "export", body: err.Error()})
		return
	}
	content := exportTranscriptText(m.transcript)
	if err := os.WriteFile(path, []byte(content), 0o600); err != nil {
		m.addEntry(transcriptEntry{kind: entryError, title: "export", body: err.Error()})
		return
	}
	if err := os.Chmod(path, 0o600); err != nil {
		m.addEntry(transcriptEntry{kind: entryError, title: "export", body: err.Error()})
		return
	}
	m.addEntry(transcriptEntry{kind: entrySystem, title: "export", body: "conversation exported to " + path})
}

func (m appModel) exportPath(arg string) (string, error) {
	root, err := os.Getwd()
	if err != nil {
		return "", err
	}
	arg = strings.TrimSpace(arg)
	if arg == "" {
		name := "conversation-" + time.Now().Format("2006-01-02-150405") + ".txt"
		return filepath.Join(root, ".ccagent", "exports", name), nil
	}
	if !strings.HasSuffix(arg, ".txt") {
		arg = strings.TrimSuffix(arg, filepath.Ext(arg)) + ".txt"
	}
	target := arg
	if !filepath.IsAbs(target) {
		target = filepath.Join(root, target)
	}
	absRoot, err := filepath.Abs(root)
	if err != nil {
		return "", err
	}
	absTarget, err := filepath.Abs(target)
	if err != nil {
		return "", err
	}
	rel, err := filepath.Rel(absRoot, absTarget)
	if err != nil {
		return "", err
	}
	if rel == ".." || strings.HasPrefix(rel, ".."+string(filepath.Separator)) {
		return "", fmt.Errorf("export path escapes workspace root: %s", arg)
	}
	return absTarget, nil
}

func exportTranscriptText(entries []transcriptEntry) string {
	var out strings.Builder
	for _, entry := range entries {
		if strings.TrimSpace(entry.body) == "" {
			continue
		}
		out.WriteString(entry.title)
		out.WriteString(":\n")
		out.WriteString(strings.TrimRight(entry.body, "\n"))
		out.WriteString("\n\n")
	}
	return out.String()
}

func (m *appModel) handleSubagentCommand(invocation string) tea.Cmd {
	req, err := m.parseSubagentCommand(invocation)
	if err != nil {
		m.addEntry(transcriptEntry{kind: entryError, title: "subagent", body: err.Error()})
		return nil
	}
	if m.subagents == nil {
		m.addEntry(transcriptEntry{kind: entryError, title: "subagent", body: "subagent controller is unavailable"})
		return nil
	}
	if req.RunMode == settings.RunModeBackground {
		task, err := m.subagents.Launch(m.ctx, req)
		if err != nil {
			m.addEntry(transcriptEntry{kind: entryError, title: "subagent", body: err.Error()})
			return nil
		}
		m.addEntry(transcriptEntry{kind: entrySystem, title: "subagent", body: renderTask(task)})
		return nil
	}
	if !m.queryGuard.StartModel() {
		m.addEntry(transcriptEntry{kind: entrySystem, title: "busy", body: "assistant is already running"})
		return nil
	}
	m.syncRunningFlags()
	m.addEntry(transcriptEntry{kind: entrySystem, title: "subagent", body: "started sync subagent"})
	return runSubagentCmd(m.ctx, m.subagents, req)
}

func (m appModel) parseSubagentCommand(invocation string) (subagent.Request, error) {
	cfg := m.currentSettings()
	req := subagent.Request{
		ParentSessionID: m.sessionID,
		ContextMode:     cfg.Subagent.DefaultContextMode,
		RunMode:         cfg.Subagent.DefaultRunMode,
	}
	fields := strings.Fields(commandArgs(invocation))
	var prompt []string
	for _, field := range fields {
		switch field {
		case "--fork":
			req.ContextMode = settings.ContextModeFork
		case "--empty":
			req.ContextMode = settings.ContextModeEmpty
		case "--background":
			req.RunMode = settings.RunModeBackground
		case "--sync":
			req.RunMode = settings.RunModeSync
		default:
			prompt = append(prompt, field)
		}
	}
	req.Prompt = strings.Join(prompt, " ")
	req.Description = summarizeToolContent(req.Prompt)
	if strings.TrimSpace(req.Prompt) == "" {
		return req, fmt.Errorf("prompt is required")
	}
	return req, nil
}

func runSubagentCmd(ctx context.Context, controller SubagentController, req subagent.Request) tea.Cmd {
	return func() tea.Msg {
		result, err := controller.Run(ctx, req)
		return subagentFinishedMsg{result: result, err: err}
	}
}

func (m *appModel) handleTasksCommand() {
	if m.subagents == nil {
		m.addEntry(transcriptEntry{kind: entryError, title: "tasks", body: "subagent controller is unavailable"})
		return
	}
	tasks := m.subagentTasks()
	if len(tasks) == 0 {
		m.addEntry(transcriptEntry{kind: entrySystem, title: "tasks", body: "no subagent tasks"})
		return
	}
	lines := make([]string, 0, len(tasks))
	for _, task := range tasks {
		lines = append(lines, renderTask(task))
	}
	m.addEntry(transcriptEntry{kind: entrySystem, title: "tasks", body: strings.Join(lines, "\n\n")})
}

func (m appModel) statusText(sessionID string) string {
	cfg := m.currentSettings()
	modelCfg := m.currentModelConfig()
	taskCount := 0
	if m.subagents != nil {
		taskCount = len(m.subagentTasks())
	}
	stats := m.contextStats()
	return fmt.Sprintf(
		"session: %s\nmodel: %s/%s\nsettings: context=%s run=%s meter=%s limit=%d\nqueue: %d\nsubagent tasks: %d\ncontext: used=%d cache=%d limit=%d",
		sessionID,
		modelCfg.Provider,
		modelCfg.Model,
		cfg.Subagent.DefaultContextMode,
		cfg.Subagent.DefaultRunMode,
		cfg.UI.ContextMeterLocation,
		cfg.UI.ContextLimitTokens,
		m.chatQueue.Len(),
		taskCount,
		stats.UsedTokens,
		stats.CacheTokens,
		stats.LimitTokens,
	)
}

func (m appModel) subagentTasks() []subagent.TaskSnapshot {
	if m.subagents == nil {
		return nil
	}
	sessionID := strings.TrimSpace(m.sessionID)
	if sessionID == "" {
		return nil
	}
	all := m.subagents.ListTasks()
	tasks := make([]subagent.TaskSnapshot, 0, len(all))
	for _, task := range all {
		if strings.TrimSpace(task.ParentSessionID) == sessionID {
			tasks = append(tasks, task)
		}
	}
	return tasks
}

func renderSubagentResult(result subagent.Result) string {
	lines := []string{
		fmt.Sprintf("done · depth %d", result.Depth),
	}
	if result.AgentID != "" {
		lines = append(lines, "id  "+result.AgentID)
	}
	if result.OutputPath != "" {
		lines = append(lines, "output  "+result.OutputPath)
	}
	if result.TranscriptPath != "" {
		lines = append(lines, "transcript  "+result.TranscriptPath)
	}
	if content := summarizeToolContent(strings.TrimSpace(result.Content)); content != "" {
		lines = append(lines, "result  "+content)
	}
	return strings.Join(lines, "\n")
}

func renderTask(task subagent.TaskSnapshot) string {
	lines := []string{
		fmt.Sprintf("%s · %s · %s · depth %d", taskDisplayName(task), task.Status, task.ContextMode, task.Depth),
	}
	if task.Name != "" && task.ID != "" {
		lines = append(lines, "id  "+task.ID)
	}
	if task.PID > 0 {
		lines = append(lines, fmt.Sprintf("pid  %d", task.PID))
	}
	if task.OutputPath != "" {
		lines = append(lines, "output  "+task.OutputPath)
	}
	if task.TranscriptPath != "" {
		lines = append(lines, "transcript  "+task.TranscriptPath)
	}
	if task.Error != "" {
		lines = append(lines, "error  "+task.Error)
	}
	if task.Content != "" {
		lines = append(lines, "result  "+summarizeToolContent(task.Content))
	}
	return strings.Join(lines, "\n")
}

func taskDisplayName(task subagent.TaskSnapshot) string {
	if name := strings.TrimSpace(task.Name); name != "" {
		return name
	}
	return shortTaskID(task.ID)
}

func resultDisplayName(result subagent.Result) string {
	if name := strings.TrimSpace(result.AgentName); name != "" {
		return name
	}
	return shortTaskID(result.AgentID)
}
